SELECT card_name, SUM(times) AS usage_times, SUM(recognized_amount) AS recognized_amount
FROM agent_v3_card_usage_view WHERE agent_v3_card_usage_view.store_id = ANY(:allowedStoreIds) AND agent_v3_card_usage_view.verified_at >= :startAt AND agent_v3_card_usage_view.verified_at < :endAt GROUP BY card_name
LIMIT 100;

SELECT project_id, project_name, price, duration
FROM agent_v3_project_catalog_view
WHERE agent_v3_project_catalog_view.store_id = ANY(:allowedStoreIds) AND (project_id = 85) LIMIT 100;

SELECT scope_type, COUNT(DISTINCT promotion_id) AS promotion_count
FROM agent_v3_promotion_offer_view WHERE agent_v3_promotion_offer_view.store_id = ANY(:allowedStoreIds) GROUP BY scope_type
LIMIT 100;

SELECT COUNT(DISTINCT reservation_id) AS reservation_count
FROM agent_v3_reservation_view
WHERE agent_v3_reservation_view.store_id = ANY(:allowedStoreIds) AND agent_v3_reservation_view.date >= :startAt AND agent_v3_reservation_view.date < :endAt AND (status NOT IN ('***')) LIMIT 1;

SELECT transfer_id, transfer_no, product_count
FROM ask_data_transfer_status_view WHERE ask_data_transfer_status_view.store_id = ANY(:allowedStoreIds) ORDER BY product_count DESC
LIMIT 10;
